import 'package:kakao_flutter_sdk_share/kakao_flutter_sdk_share.dart';

Future<void> share() async {
  final template = FeedTemplate(
    content: Content('Title', 'https://example.com', imageUrl: Uri.parse('https://example.com/img.png')),
  );
  await ShareClient.instance.shareDefault(template);
}
